const factors=[['Istituzioni','Presidenza forte, centralizzazione e controllo delle nomine ampliano il vantaggio di chi è già al potere. La Costituzione e le sue revisioni sono parte essenziale dell’analisi.'],['Partito-stato','Il RDPC/CPDM dispone di reti territoriali e di una lunga presenza nell’amministrazione e nella politica locale. “Rete” non equivale a consenso unanime.'],['Competizione','Pluralità di candidati e divisioni dell’opposizione possono disperdere voti e rendere difficile una sfida nazionale coordinata.'],['Processo elettorale','ELECAM organizza le elezioni e il Consiglio costituzionale decide sui ricorsi. Opposizioni e osservatori hanno sollevato critiche su diversi scrutini; le autorità le contestano.'],['Sicurezza','Conflitti e insicurezza, soprattutto nelle regioni anglofone e nell’Estremo Nord, incidono su vita civica, mobilità e partecipazione.']];
const chip=document.querySelector('#factorChips'),panel=document.querySelector('#factorPanel');function factor(i){[...chip.children].forEach((x,n)=>x.classList.toggle('active',n===i));panel.innerHTML=`<h3>${factors[i][0]}</h3><p>${factors[i][1]}</p><p class="note" style="margin-top:18px">Lettura strutturale: da verificare con fonti locali, dati di affluenza e testimonianze plurali.</p>`}factors.forEach((f,i)=>{let b=document.createElement('button');b.textContent=f[0];b.onclick=()=>factor(i);chip.append(b)});factor(0);
const elections=[{year:'1992',winner:'Paul Biya · RDPC/CPDM',score:'39,98%',other:'John Fru Ndi (SDF): 35,97%',note:'Prima presidenziale multipartitica; l’opposizione contestò l’esito. I risultati richiedono confronto con fonti archivistiche.'},{year:'2011',winner:'Paul Biya · RDPC/CPDM',score:'77,99%',other:'John Fru Ndi (SDF): 10,71%',note:'Molte candidature; contesto di opposizione non unificata.'},{year:'2018',winner:'Paul Biya · RDPC/CPDM',score:'71,28%',other:'Maurice Kamto (MRC): 14,23%',note:'Esito proclamato dal Consiglio costituzionale. Il rapporto ELECAM offre la lista completa dei candidati e dei ricorsi.'}];const ec=document.querySelector('#electionControls'),rc=document.querySelector('#resultCard');function election(i){[...ec.children].forEach((x,n)=>x.classList.toggle('active',n===i));let e=elections[i];rc.innerHTML=`<p class="eyebrow">PRESIDENZIALI ${e.year}</p><h3>${e.winner}</h3><div class="score"><b>${e.score}</b><span>quota ufficiale dei voti validi</span></div><div class="bar"><i style="width:${e.score.replace(',','.').replace('%','')}%"></i></div><p><strong>Principale sfidante:</strong> ${e.other}</p><p class="note" style="margin-top:18px">${e.note}</p>`}elections.forEach((e,i)=>{let b=document.createElement('button');b.textContent=e.year;b.onclick=()=>election(i);ec.append(b)});election(2);
const groups=[['Bantu e semi-bantu','Famiglie molto ampie presenti in varie regioni, incluse comunità costiere, meridionali e orientali; le denominazioni non descrivono una posizione politica comune.'],['Grassfields / Camerun occidentale','Molte comunità dell’altopiano occidentale con sistemi locali e lingue differenti; spesso analizzate separatamente per storia regionale.'],['Sawa','Termine ombrello per diverse comunità costiere; identità urbana, lingua e appartenenza politica non coincidono necessariamente.'],['Fulani/Fulɓe e popolazioni saheliane','Presenze importanti nel nord, accanto a numerose altre comunità; le dinamiche locali includono pastorizia, commercio, religione e sicurezza.'],['Kirdi / popoli montani','Espressione storica ampia e discussa, che raccoglie molte comunità del Nord e dell’Estremo Nord: evitare di trattarla come una sola etnia.'],['Popolazioni indigene forestali','Tra cui gruppi spesso indicati come Baka, Bagyeli e Bakola; diritti fondiari, accesso ai servizi e rappresentanza sono temi ricorrenti.']];const gl=document.querySelector('#groupList');groups.forEach(([n,d])=>{let x=document.createElement('div');x.className='group';x.innerHTML=`<button aria-expanded="false">${n} +</button><p>${d}</p>`;x.querySelector('button').onclick=()=>{x.classList.toggle('open');x.querySelector('button').setAttribute('aria-expanded',x.classList.contains('open'));x.querySelector('button').textContent=n+(x.classList.contains('open')?' −':' +')};gl.append(x)});
